30	  /**
31	   * POST: /api/upload
32	   * Update library item
33	   *
34	   * @param {RequestWithUser} req
35	   * @param {Response} res
36	   */
37	  async handleUpload(req, res) {
38	    if (!req.user.canUpload) {
39	      Logger.warn(`User "${req.user.username}" attempted to upload without permission`)
40	      return res.sendStatus(403)
41	    }
42	    if (!req.files || !Object.values(req.files).length) {
43	      Logger.error('Invalid request, no files')
44	      return res.sendStatus(400)
45	    }
46	
47	    const files = Object.values(req.files)
48	    let { title, author, series, folder: folderId, library: libraryId } = req.body
49	    // Validate request body
50	    if (!libraryId || !folderId || typeof libraryId !== 'string' || typeof folderId !== 'string' || !title || typeof title !== 'string') {
51	      return res.status(400).send('Invalid request body')
52	    }
53	    if (!series || typeof series !== 'string') {
54	      series = null
55	    }
56	    if (!author || typeof author !== 'string') {
57	      author = null
58	    }
59	
60	    const library = await Database.libraryModel.findByIdWithFolders(libraryId)
61	    if (!library) {
62	      return res.status(404).send('Library not found')
63	    }
64	
65	    if (!req.user.checkCanAccessLibrary(library.id)) {
66	      Logger.error(`[MiscController] User "${req.user.username}" attempting to upload to library "${library.id}" without access`)
67	      return res.sendStatus(403)
68	    }
69	
70	    const folder = library.libraryFolders.find((fold) => fold.id === folderId)
71	    if (!folder) {
72	      return res.status(404).send('Folder not found')
73	    }
74	
75	    // Podcasts should only be one folder deep
76	    const outputDirectoryParts = library.isPodcast ? [title] : [author, series, title]
77	    // `.filter(Boolean)` to strip out all the potentially missing details (eg: `author`)
78	    // before sanitizing all the directory parts to remove illegal chars and finally prepending
79	    // the base folder path
80	    const cleanedOutputDirectoryParts = outputDirectoryParts.filter(Boolean).map((part) => sanitizeFilename(part))
81	    const outputDirectory = Path.join(...[folder.path, ...cleanedOutputDirectoryParts])
82	
83	    try {
84	      await fs.ensureDir(outputDirectory)
85	    } catch (error) {
86	      Logger.error('[MiscController] Failed to create upload directory', outputDirectory, error)
87	      return res.sendStatus(500)
88	    }
89	
90	    Logger.info(`Uploading ${files.length} files to`, outputDirectory)
91	
92	    for (const file of files) {
93	      const path = Path.join(outputDirectory, sanitizeFilename(file.name))
94	
95	      await file
96	        .mv(path)
97	        .then(() => {
98	          return true
99	        })
100	        .catch((error) => {
101	          Logger.error('Failed to move file', path, error)
102	          return false
103	        })
104	    }
105	
106	    res.sendStatus(200)
107	  }
