132	  /**
133	   * PATCH: /api/settings
134	   * Update server settings
135	   *
136	   * @param {RequestWithUser} req
137	   * @param {Response} res
138	   */
139	  async updateServerSettings(req, res) {
140	    if (!req.user.isAdminOrUp) {
141	      Logger.error(`User "${req.user.username}" other than admin attempting to update server settings`)
142	      return res.sendStatus(403)
143	    }
144	    const settingsUpdate = req.body
145	    if (!isObject(settingsUpdate)) {
146	      return res.status(400).send('Invalid settings update object')
147	    }
148	    if (settingsUpdate.allowIframe == false && process.env.ALLOW_IFRAME === '1') {
149	      Logger.warn('Cannot disable iframe when ALLOW_IFRAME is enabled in environment')
150	      return res.status(400).send('Cannot disable iframe when ALLOW_IFRAME is enabled in environment')
151	    }
152	    const filteredUpdate = {}
153	    for (const key in settingsUpdate) {
154	      if (ServerSettings.patchableSettingsKeys.has(key)) {
155	        filteredUpdate[key] = settingsUpdate[key]
156	      }
157	    }
158	
159	    if (filteredUpdate.allowedOrigins && !Array.isArray(filteredUpdate.allowedOrigins)) {
160	      return res.status(400).send('allowedOrigins must be an array')
161	    }
162	
163	    const madeUpdates = Database.serverSettings.update(filteredUpdate)
164	    if (madeUpdates) {
165	      await Database.updateServerSettings()
166	
167	      // If backup schedule is updated - update backup manager
168	      if (filteredUpdate.backupSchedule !== undefined) {
169	        this.backupManager.updateCronSchedule()
170	      }
171	    }
172	    return res.json({
173	      serverSettings: Database.serverSettings.toJSONForBrowser()
174	    })
175	  }
