221	      })
222	    }
223	
224	    // Update titleIgnorePrefix column on podcasts
225	    const podcasts = await Database.podcastModel.findAll({
226	      attributes: ['id', 'title', 'titleIgnorePrefix']
227	    })
228	    const bulkUpdatePodcasts = []
229	    podcasts.forEach((podcast) => {
230	      const titleIgnorePrefix = getTitleIgnorePrefix(podcast.title)
231	      if (titleIgnorePrefix !== podcast.titleIgnorePrefix) {
232	        bulkUpdatePodcasts.push({
233	          id: podcast.id,
234	          titleIgnorePrefix
235	        })
236	      }
237	    })
238	    if (bulkUpdatePodcasts.length) {
239	      Logger.info(`[MiscController] Updating titleIgnorePrefix on ${bulkUpdatePodcasts.length} podcasts`)
240	      rowsUpdated += bulkUpdatePodcasts.length
241	      await Database.podcastModel.bulkCreate(bulkUpdatePodcasts, {
242	        updateOnDuplicate: ['titleIgnorePrefix']
243	      })
244	    }
245	
246	    // Update nameIgnorePrefix column on series
247	    const allSeries = await Database.seriesModel.findAll({
248	      attributes: ['id', 'name', 'nameIgnorePrefix', 'libraryId']
249	    })
250	    const bulkUpdateSeries = []
251	    allSeries.forEach((series) => {
252	      const nameIgnorePrefix = getTitleIgnorePrefix(series.name)
253	      if (nameIgnorePrefix !== series.nameIgnorePrefix) {
