333	  /**
334	   * POST: /api/tags/rename
335	   * Rename tag
336	   * Req.body { tag, newTag }
337	   *
338	   * @param {RequestWithUser} req
339	   * @param {Response} res
340	   */
341	  async renameTag(req, res) {
342	    if (!req.user.isAdminOrUp) {
343	      Logger.error(`[MiscController] Non-admin user "${req.user.username}" attempted to renameTag`)
344	      return res.sendStatus(403)
345	    }
346	
347	    const tag = req.body.tag
348	    const newTag = req.body.newTag
349	    if (!tag || !newTag) {
350	      Logger.error(`[MiscController] Invalid request body for renameTag`)
351	      return res.sendStatus(400)
352	    }
353	
354	    let tagMerged = false
355	    let numItemsUpdated = 0
356	
357	    // Update filter data
358	    Database.replaceTagInFilterData(tag, newTag)
359	
360	    const libraryItemsWithTag = await libraryItemFilters.getAllLibraryItemsWithTags([tag, newTag])
361	    for (const libraryItem of libraryItemsWithTag) {
362	      if (libraryItem.media.tags.includes(newTag)) {
363	        tagMerged = true // new tag is an existing tag so this is a merge
364	      }
365	
366	      if (libraryItem.media.tags.includes(tag)) {
367	        libraryItem.media.tags = libraryItem.media.tags.filter((t) => t !== tag) // Remove old tag
368	        if (!libraryItem.media.tags.includes(newTag)) {
369	          libraryItem.media.tags.push(newTag)
370	        }
371	        Logger.debug(`[MiscController] Rename tag "${tag}" to "${newTag}" for item "${libraryItem.media.title}"`)
372	        await libraryItem.media.update({
373	          tags: libraryItem.media.tags
374	        })
375	        await libraryItem.saveMetadataFile()
376	
377	        SocketAuthority.libraryItemEmitter('item_updated', libraryItem)
378	        numItemsUpdated++
379	      }
380	    }
381	
382	    res.json({
383	      tagMerged,
384	      numItemsUpdated
385	    })
386	  }
