567	  /**
568	   * POST: /api/watcher/update
569	   * Update a watch path
570	   * Req.body { libraryId, path, type, [oldPath] }
571	   * type = add, unlink, rename
572	   * oldPath = required only for rename
573	   *
574	   * @this import('../routers/ApiRouter')
575	   *
576	   * @param {RequestWithUser} req
577	   * @param {Response} res
578	   */
579	  updateWatchedPath(req, res) {
580	    if (!req.user.isAdminOrUp) {
581	      Logger.error(`[MiscController] Non-admin user "${req.user.username}" attempted to updateWatchedPath`)
582	      return res.sendStatus(403)
583	    }
584	
585	    const libraryId = req.body.libraryId
586	    const path = req.body.path
587	    const type = req.body.type
588	    if (!libraryId || !path || !type) {
589	      Logger.error(`[MiscController] Invalid request body for updateWatchedPath. libraryId: "${libraryId}", path: "${path}", type: "${type}"`)
590	      return res.sendStatus(400)
591	    }
592	
593	    switch (type) {
594	      case 'add':
595	        Watcher.onFileAdded(libraryId, path)
596	        break
597	      case 'unlink':
598	        Watcher.onFileRemoved(libraryId, path)
599	        break
600	      case 'rename':
601	        const oldPath = req.body.oldPath
602	        if (!oldPath) {
603	          Logger.error(`[MiscController] Invalid request body for updateWatchedPath. oldPath is required for rename.`)
604	          return res.sendStatus(400)
605	        }
606	        Watcher.onFileRename(libraryId, oldPath, path)
607	        break
608	      default:
609	        Logger.error(`[MiscController] Invalid type for updateWatchedPath. type: "${type}"`)
610	        return res.sendStatus(400)
611	    }
612	
613	    res.sendStatus(200)
614	  }
