// Query values are assumed to be strings (the original code calls .split and .trim on them); the middleware replaces limit and page with numbers before a handler runs
type LibraryQuery = { include?: string; limit?: number; page?: number; sort?: string; desc?: string; filter?: string; minified?: string; collapseseries?: string; q?: string; force?: string; ext?: string; ids?: string }
type LibraryParams = { id: string; seriesId: string; narratorId: string }
// A folder as the client sends it in the body of create() and update(): only the members the code reads
type FolderPayload = { id?: string; fullPath?: string; path?: string }
type LibraryBody = { name?: string; folders?: FolderPayload[]; settings?: { [key: string]: unknown }; displayOrder?: number; provider?: string; [key: string]: unknown } // index signatures: create() and update() read req.body and req.body.settings by a dynamic key
type RequestUserObject = { user: User }
type RequestWithUser = Request<LibraryParams, unknown, LibraryBody, LibraryQuery> & RequestUserObject
type RequestEntityObject = { library: Library }
type LibraryControllerRequest = RequestWithUser & RequestEntityObject
type LibraryReorderObj = { id: string; newOrder: number }
type LibraryReorderRequest = Request<{}, {}, LibraryReorderObj[], {}> & RequestUserObject
// The middleware sets library, and it reads limit and page as strings and writes them back as numbers
type MiddlewareQuery = { [key: string]: string | number | undefined } // index signature: the middleware reads and assigns req.query by a dynamic key
type LibraryMiddlewareRequest = Request<LibraryParams, unknown, LibraryBody, MiddlewareQuery> & RequestUserObject & { library?: Library }

