// Single-file transpile of one .ts file into the scratchpad (writes nothing in the repo).
// Usage (cwd = repo root): node a4-transpile.js <input.ts> <output.js>
const fs = require('fs')
const path = require('path')
const ts = require(require.resolve('typescript', { paths: [process.cwd()] }))

const [input, output] = process.argv.slice(2)
const configPath = path.join(process.cwd(), 'tsconfig.server.json')
const config = ts.readConfigFile(configPath, ts.sys.readFile)
const parsed = ts.convertCompilerOptionsFromJson(config.config.compilerOptions, process.cwd())
const options = { ...parsed.options, incremental: false, tsBuildInfoFile: undefined, noEmitOnError: false, isolatedModules: false }

const source = fs.readFileSync(input, 'utf8')
const result = ts.transpileModule(source, { compilerOptions: options, fileName: path.basename(input), reportDiagnostics: true })
fs.writeFileSync(output, result.outputText)
console.log('typescript', ts.version, '| diagnostics:', (result.diagnostics || []).length, '| wrote', output)

